update known_safe_harbors set tissue_context = 'H9 hESC line, differentiated into neurons' where source_pmid = '38244534' and evidence_summary = 'H9 hESC line with a doxycycline-inducible NGN2 cassette at the CLYBL locus. Remains pluripotent without doxycycline; transitions rapidly to a neuronal state upon induction -- same functional pattern already seen at AAVS1 (earlier batches), now confirmed at CLYBL too.';
update public_safe_harbors_staging set tissue_context = 'H9 hESC line, differentiated into neurons' where source_pmid = '38244534' and evidence_summary = 'H9 hESC line with a doxycycline-inducible NGN2 cassette at the CLYBL locus. Remains pluripotent without doxycycline; transitions rapidly to a neuronal state upon induction -- same functional pattern already seen at AAVS1 (earlier batches), now confirmed at CLYBL too.';

update known_safe_harbors set tissue_context = 'Mouse liver, in vivo disease model' where source_pmid = '26865405' and evidence_summary = 'G6PC transgene (glucose-6-phosphatase deficiency, glycogen storage disease type Ia) inserted at ROSA26 via ZFN + AAV. Survival of G6Pase-KO mice significantly improved compared to receiving the donor vector alone. Notable finding: targeted alleles became 4.6x MORE common in the liver of diseased mice vs. healthy controls at 8 months -- suggesting a real selective advantage of corrected liver cells, a concrete example of somatic selection (the theoretical mechanism discussed earlier) actually happening in an animal model.';
update public_safe_harbors_staging set tissue_context = 'Mouse liver, in vivo disease model' where source_pmid = '26865405' and evidence_summary = 'G6PC transgene (glucose-6-phosphatase deficiency, glycogen storage disease type Ia) inserted at ROSA26 via ZFN + AAV. Survival of G6Pase-KO mice significantly improved compared to receiving the donor vector alone. Notable finding: targeted alleles became 4.6x MORE common in the liver of diseased mice vs. healthy controls at 8 months -- suggesting a real selective advantage of corrected liver cells, a concrete example of somatic selection (the theoretical mechanism discussed earlier) actually happening in an animal model.';

update known_safe_harbors set tissue_context = 'Human CD34+ HSPCs, myeloid-lineage-specific regulation observed in a subset' where source_pmid = '41438051' and evidence_summary = 'Original approach: mapped 102 EPV loci (evolutionarily conserved endogenous parvoviral elements) in the human genome, 17 experimentally evaluated as safe-harbor candidates in CD34+ HSPCs. At least 6 tolerant to transgene insertion with low transcriptome disruption; 3 showed myeloid-lineage-specific regulation. Individual locus names/coordinates were not in the abstract -- candidate for full-text mining if exact names are wanted.';
update public_safe_harbors_staging set tissue_context = 'Human CD34+ HSPCs, myeloid-lineage-specific regulation observed in a subset' where source_pmid = '41438051' and evidence_summary = 'Original approach: mapped 102 EPV loci (evolutionarily conserved endogenous parvoviral elements) in the human genome, 17 experimentally evaluated as safe-harbor candidates in CD34+ HSPCs. At least 6 tolerant to transgene insertion with low transcriptome disruption; 3 showed myeloid-lineage-specific regulation. Individual locus names/coordinates were not in the abstract -- candidate for full-text mining if exact names are wanted.';

