update known_safe_harbors set tissue_context = 'Human CD34+ HSPCs (mobilized peripheral blood and fetal liver); long-term engraftment in immunodeficient mice' where source_pmid = '26551060' and evidence_summary = 'Direct CCR5 vs. AAVS1 comparison in human CD34+ HSPCs (ZFN mRNA + AAV6 donor): integration frequencies of 26% (mobilized peripheral blood) and 43% (fetal liver) at AAVS1, higher than those obtained at CCR5 in the same study (see paired CCR5 record). Modification confirmed in the rare CD34+CD133+CD90+ subpopulation (long-term hematopoietic stem cells), with long-term engraftment in immunodeficient mice.';
update public_safe_harbors_staging set tissue_context = 'Human CD34+ HSPCs (mobilized peripheral blood and fetal liver); long-term engraftment in immunodeficient mice' where source_pmid = '26551060' and evidence_summary = 'Direct CCR5 vs. AAVS1 comparison in human CD34+ HSPCs (ZFN mRNA + AAV6 donor): integration frequencies of 26% (mobilized peripheral blood) and 43% (fetal liver) at AAVS1, higher than those obtained at CCR5 in the same study (see paired CCR5 record). Modification confirmed in the rare CD34+CD133+CD90+ subpopulation (long-term hematopoietic stem cells), with long-term engraftment in immunodeficient mice.';

update known_safe_harbors set tissue_context = 'Human CD34+ HSPCs (mobilized peripheral blood and fetal liver); long-term engraftment in immunodeficient mice' where source_pmid = '26551060' and evidence_summary = 'Same study: integration frequencies at CCR5 of 17% (mobilized peripheral blood) and 19% (fetal liver) -- lower than those obtained at AAVS1 in the same study, but still effective for modifying long-term hematopoietic stem cells (CD34+CD133+CD90+) with confirmed engraftment.';
update public_safe_harbors_staging set tissue_context = 'Human CD34+ HSPCs (mobilized peripheral blood and fetal liver); long-term engraftment in immunodeficient mice' where source_pmid = '26551060' and evidence_summary = 'Same study: integration frequencies at CCR5 of 17% (mobilized peripheral blood) and 19% (fetal liver) -- lower than those obtained at AAVS1 in the same study, but still effective for modifying long-term hematopoietic stem cells (CD34+CD133+CD90+) with confirmed engraftment.';

update known_safe_harbors set tissue_context = 'Real clinical trial patients (adrenoleukodystrophy), hematopoietic cells' where source_pmid = '21403130' and evidence_summary = 'Analysis of common integration sites (CIS) in a real adrenoleukodystrophy clinical trial with a lentiviral vector: observed CIS cluster in broad (megabase-scale) chromosomal regions of high lentiviral integration density -- a benign integration bias, not oncogenic selection. Contrasts with CIS from gammaretroviral vectors in trials that caused cancer, which always target a single gene in narrow genomic intervals. Relatively good news specifically for lentivirus, but still not a named safe harbor.';
update public_safe_harbors_staging set tissue_context = 'Real clinical trial patients (adrenoleukodystrophy), hematopoietic cells' where source_pmid = '21403130' and evidence_summary = 'Analysis of common integration sites (CIS) in a real adrenoleukodystrophy clinical trial with a lentiviral vector: observed CIS cluster in broad (megabase-scale) chromosomal regions of high lentiviral integration density -- a benign integration bias, not oncogenic selection. Contrasts with CIS from gammaretroviral vectors in trials that caused cancer, which always target a single gene in narrow genomic intervals. Relatively good news specifically for lentivirus, but still not a named safe harbor.';

update known_safe_harbors set tissue_context = 'In vitro CAR-T assay; in vivo NOD/SCID mouse solid-tumor model' where source_pmid = '33627635' and evidence_summary = 'Nanobody-based (not conventional antibody) anti-CD105 CAR-T inserted at AAVS1 -- activation, proliferation, pro-inflammatory cytokine production, and specific killing of CD105+ target cells in vitro. In vivo, significantly inhibited implanted tumor growth and prolonged survival in NOD/SCID mice -- a rare solid-tumor data point, not just hematologic malignancy.';
update public_safe_harbors_staging set tissue_context = 'In vitro CAR-T assay; in vivo NOD/SCID mouse solid-tumor model' where source_pmid = '33627635' and evidence_summary = 'Nanobody-based (not conventional antibody) anti-CD105 CAR-T inserted at AAVS1 -- activation, proliferation, pro-inflammatory cytokine production, and specific killing of CD105+ target cells in vitro. In vivo, significantly inhibited implanted tumor growth and prolonged survival in NOD/SCID mice -- a rare solid-tumor data point, not just hematologic malignancy.';

update known_safe_harbors set tissue_context = 'Cell type not specified in evidence text (delivery-method efficiency study)' where source_pmid = '33496003' and evidence_summary = 'A specific delivery method tested (dCas9-piggyBac transposase fusion with dual sgRNAs) for targeted integration at ROSA26 had very low efficiency: only 0.32% of cells. Not necessarily a locus failure, more a limitation of the delivery method tested -- but a real low-efficiency data point worth recording.';
