update known_safe_harbors set tissue_context = 'General calibration/opinion note, not tied to a specific cell type or experiment' where source_pmid = '26867951' and evidence_summary = 'Relevant citation from the very group that defined genomic safe-harbor criteria (Papapetrou and colleagues), reviewing their own criteria: "currently, there are no fully validated genomic safe harbors in the human genome". Worth using as a calibration -- even AAVS1/ROSA26/H11, despite being widely used, do not meet all the rigorous, fully validated criteria according to the definition''s own authors.';
update public_safe_harbors_staging set tissue_context = 'General calibration/opinion note, not tied to a specific cell type or experiment' where source_pmid = '26867951' and evidence_summary = 'Relevant citation from the very group that defined genomic safe-harbor criteria (Papapetrou and colleagues), reviewing their own criteria: "currently, there are no fully validated genomic safe harbors in the human genome". Worth using as a calibration -- even AAVS1/ROSA26/H11, despite being widely used, do not meet all the rigorous, fully validated criteria according to the definition''s own authors.';

update known_safe_harbors set tissue_context = 'Structural/biochemical study, not cell-type specific (in vitro protein-DNA assembly)' where source_pmid = '26370092' and evidence_summary = 'Structural (X-ray) detail of how the AAV Rep68 protein recognizes and assembles at the AAVS1 site: multiple GCTC repeats recognized by a glycine-rich loop and a helix interacting with the minor groove; the full heptameric complex requires a minimum of two direct repeats to form and melt the DNA. Explains at the molecular level the specificity of integration at this locus.';
update public_safe_harbors_staging set tissue_context = 'Structural/biochemical study, not cell-type specific (in vitro protein-DNA assembly)' where source_pmid = '26370092' and evidence_summary = 'Structural (X-ray) detail of how the AAV Rep68 protein recognizes and assembles at the AAVS1 site: multiple GCTC repeats recognized by a glycine-rich loop and a helix interacting with the minor groove; the full heptameric complex requires a minimum of two direct repeats to form and melt the DNA. Explains at the molecular level the specificity of integration at this locus.';

update known_safe_harbors set tissue_context = 'Human population genetics finding, not a specific cell type (natural polymorphism prevalence)' where source_pmid = '24334609' and evidence_summary = 'Reinforces the biological caveat already on record: CLYBL encodes a real malate/beta-methylmalate synthase enzyme, linked to the mitochondrial vitamin B12 pathway. About 5% of all humans naturally carry a premature-stop polymorphism in CLYBL (complete loss of protein expression) associated with reduced circulating B12 levels -- a reassuring precedent: CLYBL loss-of-function already exists naturally in a substantial fraction of the human population with an apparently mild effect.';
update public_safe_harbors_staging set tissue_context = 'Human population genetics finding, not a specific cell type (natural polymorphism prevalence)' where source_pmid = '24334609' and evidence_summary = 'Reinforces the biological caveat already on record: CLYBL encodes a real malate/beta-methylmalate synthase enzyme, linked to the mitochondrial vitamin B12 pathway. About 5% of all humans naturally carry a premature-stop polymorphism in CLYBL (complete loss of protein expression) associated with reduced circulating B12 levels -- a reassuring precedent: CLYBL loss-of-function already exists naturally in a substantial fraction of the human population with an apparently mild effect.';

update known_safe_harbors set tissue_context = 'Mechanistic/virological study, not a specific cell type (AAV episomal vs. chromosomal persistence)' where source_pmid = '15568995' and evidence_summary = 'Important mechanistic nuance (2004): the NATURAL integration of wild-type AAV at AAVS1 (Rep-mediated, not CRISPR) is actually inefficient in any context -- the persistence of AAV delivery vectors in tissues is largely due to episomal genomes, not true chromosomal integration. This does not contradict data on CRISPR/nuclease-targeted insertion at AAVS1 (a different mechanism, via HDR after a directed cut), but is a reminder that the natural biology of AAV itself is not the same process as modern gene editing at this locus.';
update public_safe_harbors_staging set tissue_context = 'Mechanistic/virological study, not a specific cell type (AAV episomal vs. chromosomal persistence)' where source_pmid = '15568995' and evidence_summary = 'Important mechanistic nuance (2004): the NATURAL integration of wild-type AAV at AAVS1 (Rep-mediated, not CRISPR) is actually inefficient in any context -- the persistence of AAV delivery vectors in tissues is largely due to episomal genomes, not true chromosomal integration. This does not contradict data on CRISPR/nuclease-targeted insertion at AAVS1 (a different mechanism, via HDR after a directed cut), but is a reminder that the natural biology of AAV itself is not the same process as modern gene editing at this locus.';

