update known_safe_harbors set tissue_context = 'Not locus-specific -- an add-on regulatory element; validated in vivo in engrafted hematopoietic cells' where source_pmid = '20588258' and evidence_summary = 'Not a locus, it is a regulatory element that attaches to ANY construct to protect it from silencing: A2UCOE (derived from the housekeeping HNRPA2B1-CBX3 locus) confers resistance to DNA-methylation-mediated silencing of lentiviral vectors. SFFV/EF1a promoters alone silenced within 16 days; linked upstream of A2UCOE, they remained completely stable, with near-total resistance to CpG methylation -- also confirmed in vivo in engrafted hematopoietic cells. A complementary tool to whichever safe-harbor locus is chosen, not a substitute for one.';
update public_safe_harbors_staging set tissue_context = 'Not locus-specific -- an add-on regulatory element; validated in vivo in engrafted hematopoietic cells' where source_pmid = '20588258' and evidence_summary = 'Not a locus, it is a regulatory element that attaches to ANY construct to protect it from silencing: A2UCOE (derived from the housekeeping HNRPA2B1-CBX3 locus) confers resistance to DNA-methylation-mediated silencing of lentiviral vectors. SFFV/EF1a promoters alone silenced within 16 days; linked upstream of A2UCOE, they remained completely stable, with near-total resistance to CpG methylation -- also confirmed in vivo in engrafted hematopoietic cells. A complementary tool to whichever safe-harbor locus is chosen, not a substitute for one.';

update known_safe_harbors set tissue_context = 'Historical structural/cytogenetic mapping study, not cell-type specific' where source_pmid = '1657596' and evidence_summary = 'Historical founding paper (1991): first mapping of AAV integration to human chromosome 19, distal q arm, confirmed by in situ hybridization as q13.4-ter. Integration breakpoints occur within a cellular region of only 100 base pairs -- the original discovery that gave rise to the name "AAVS1".';
